def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    slots = max(1, int(supply / WATER_REQ))
    scarcity = 0
    if slots <= 1:
        scarcity = 2
    elif slots <= 2:
        scarcity = 1

    highest_prev = 0.0
    cindy_prev = None
    desperate_count = 0
    rich_alive = 0
    for agent_id, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_alive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                b = float(bid)
            except Exception:
                b = 0.0
            if b > highest_prev:
                highest_prev = b
            if agent_id == 'Cindy':
                cindy_prev = b

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 1:
        urgency += 2
    urgency += scarcity

    target = DAILY_SALARY * 0.42

    if cindy_prev is not None:
        if urgency >= 4:
            target = max(target, min(cindy_prev + 3.0, DAILY_SALARY * 1.6))
        elif urgency >= 2:
            target = max(target, min(cindy_prev * 0.82 + 2.0, DAILY_SALARY * 1.15))
        else:
            target = max(target, min(cindy_prev * 0.58, DAILY_SALARY * 0.72))
    elif highest_prev > 0:
        if urgency >= 4:
            target = max(target, min(highest_prev + 2.0, DAILY_SALARY * 1.35))
        elif urgency >= 2:
            target = max(target, min(highest_prev * 0.8 + 1.0, DAILY_SALARY))
        else:
            target = max(target, min(highest_prev * 0.55, DAILY_SALARY * 0.7))

    if scarcity == 2 and urgency >= 3:
        target = max(target, DAILY_SALARY * 1.18)
    elif scarcity == 1 and urgency >= 2:
        target = max(target, DAILY_SALARY * 0.82)

    if rich_alive <= 1 and desperate_count >= 1 and urgency <= 2:
        target *= 0.82

    if hp >= 7 and no_water_days == 0 and scarcity == 0:
        target = min(target, DAILY_SALARY * 0.45)

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(budget, max(DAILY_SALARY * 0.35, budget / (reserve_days + 0.5) * 1.35))

    if urgency >= 5:
        soft_cap = budget
    elif urgency >= 3:
        soft_cap = min(budget, max(soft_cap, DAILY_SALARY * 0.95))

    bid = min(target, soft_cap)
    if hp <= 1 or no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 1.25, highest_prev + 4.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Immediate reaction to yesterday bids
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Supply pressure heuristic: with more supply, fewer players need to overbid
    # but opponents already overbid yesterday (~100). We counter with a controlled bid.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    supply_norm = 0.0 if supply_norm < 0.0 else (1.0 if supply_norm > 1.0 else supply_norm)

    # Base bid level tied to yesterday's aggressiveness
    # If opponents were very aggressive, we match moderately; if not, we shade upward.
    if highest_prev >= DAILY_SALARY * 0.85:
        # They likely bid to secure water; avoid getting outbid by bidding near their level but with a cap.
        base = DAILY_SALARY * (0.55 + 0.25 * supply_norm)
    else:
        base = max(DAILY_SALARY * 0.45, avg_prev * 0.85 + 5.0)

    # My urgency: low hp or many no-water days => bid more
    urgency = 0.0
    if hp <= 2.0:
        urgency = 0.35
    elif hp <= 4.0:
        urgency = 0.2
    else:
        urgency = 0.05

    if no_water_days >= 2:
        urgency += 0.15

    bid = base * (1.0 + urgency)

    # If my hp is extremely low, ensure survival attempt
    if hp <= 1.0:
        bid = max(bid, DAILY_SALARY * 0.85)

    # Budget safety
    bid = min(bid, budget)

    # Keep bids within reasonable bounds to avoid overspending
    # (still allow aggressive bids when needed)
    min_bid = 0.0
    max_bid = min(budget, DAILY_SALARY * 1.1)
    if bid < min_bid:
        bid = min_bid
    if bid > max_bid:
        bid = max_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    # Base bid: if critical HP, go high
    if my_hp <= 2:
        target = min(my_budget, DAILY_SALARY * 0.9)
    else:
        # Decide based on previous bids
        if prev_bids:
            max_prev = max(prev_bids)
            target = min(my_budget, max(max_prev + 1.5, DAILY_SALARY * 0.4))
        else:
            target = min(my_budget, DAILY_SALARY * 0.55)
    # Clamp to 0 and budget
    return max(0.0, target)
